import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const APP_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

export const GENERATED_CLIENT_MODULE_PATH = path.join(
  APP_ROOT,
  'src/donation-forms/embed-client/donation-form-client-script.generated.ts',
);

const ENTRY_SOURCE = `import { startDonationFormFromDocument } from 'src/donation-forms/embed-client/donation-form-client';
startDonationFormFromDocument(window);
`;

export const bundleDonationFormClient = async () => {
  const result = await build({
    stdin: {
      contents: ENTRY_SOURCE,
      resolveDir: APP_ROOT,
      loader: 'ts',
      sourcefile: 'donation-form-client-entry.ts',
    },
    bundle: true,
    format: 'iife',
    platform: 'browser',
    target: ['es2020'],
    tsconfig: path.join(APP_ROOT, 'tsconfig.json'),
    write: false,
    // Unminified so reviewers can read what runs on the donor's page.
    minify: false,
    legalComments: 'none',
    charset: 'utf8',
    logLevel: 'silent',
  });

  const script = result.outputFiles[0]?.text ?? '';

  // The script is inlined into an HTML <script> element.
  if (/<\/script|<!--/i.test(script)) {
    throw new Error('Donation form client contains "</script" or "<!--"');
  }

  return script;
};

export const renderGeneratedClientModule = (script) =>
  '// Generated by scripts/build-donation-form-client.mjs from\n' +
  '// src/donation-forms/embed-client. Do not edit; run `yarn build:donation-form-client`.\n' +
  // One entry per line keeps diffs of the generated file reviewable.
  'export const DONATION_FORM_CLIENT_SCRIPT = [\n' +
  script
    .split('\n')
    .map((line) => `  ${JSON.stringify(line)},\n`)
    .join('') +
  "].join('\\n');\n";
